var n=`0527-sabzi-polo-ba-mahi`;var t=`world-0527`;var a=`IR`;var o=`western-asia`;var r=4;var l=69;var s={en:`Sabzi Polo ba Mahi`,ua:`Сабзі-поло з рибою`};var d={en:`A traditional dish from Iran, centered on basmati rice, parsley, dill, cilantro. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Іран. Основні складники: рис басматі, петрушка, кріп, кінза. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Cook the listed ingredients in simmering water for about 11 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 11 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:11,i:[[`basmati-rice`,450,`g`],[`water`,1400,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`parsley`,100,`g`],[`dill`,95,`g`],[`cilantro`,75,`g`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 35 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 35 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:35,i:[[`unsalted-butter`,65,`g`],[`saffron-threads`,.35,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`trout`,650,`g`],[`extra-virgin-olive-oil`,60,`ml`],[`lemon-juice`,45,`ml`]]}];var m={slug:n,id:t,country:`IR`,region:o,servings:4,minutes:69,title:s,text:d,steps:u};export{a as country,m as default,t as id,l as minutes,o as region,r as servings,n as slug,u as steps,d as text,s as title};